<span class="line"><span class="__shiki_1itgoe">WHERE</span><span class="__shiki_dzsirb"> all</span><span class="__shiki_140thh">(i </span><span class="__shiki_1itgoe">in</span><span class="__shiki_dzsirb"> range</span><span class="__shiki_140thh">(</span><span class="__shiki_dzsirb">0</span><span class="__shiki_140thh">, size(rels)</span><span class="__shiki_1itgoe">-</span><span class="__shiki_dzsirb">1</span><span class="__shiki_140thh">) </span></span>
