<span class="line"><span class="__shiki_1itgoe">          AND</span><span class="__shiki_140thh"> (i </span><span class="__shiki_1itgoe">=</span><span class="__shiki_dzsirb"> 0</span><span class="__shiki_1itgoe"> OR</span><span class="__shiki_140thh"> rels[i].timestamp </span><span class="__shiki_1itgoe">&gt;=</span><span class="__shiki_140thh"> rels[i</span><span class="__shiki_1itgoe">-</span><span class="__shiki_dzsirb">1</span><span class="__shiki_140thh">].timestamp))</span></span>
