<span class="line"><span class="__shiki_1itgoe">MATCH</span><span class="__shiki_140thh"> path </span><span class="__shiki_1itgoe">=</span><span class="__shiki_140thh"> (employee:Person)</span><span class="__shiki_dzsirb">-</span><span class="__shiki_1itgoe">[:</span><span class="__shiki_1t8gfj">MANAGES</span><span class="__shiki_dzsirb">*0..5</span><span class="__shiki_1itgoe">]</span><span class="__shiki_dzsirb">-&gt;</span><span class="__shiki_140thh">(subordinate:Person)</span></span>
