<span class="line"><span class="__shiki_1itgoe">MATCH</span><span class="__shiki_140thh"> path </span><span class="__shiki_1itgoe">=</span><span class="__shiki_140thh"> (a:City)</span><span class="__shiki_dzsirb">-</span><span class="__shiki_1itgoe">[:</span><span class="__shiki_1t8gfj">CONNECTED</span><span class="__shiki_dzsirb">*1..10</span><span class="__shiki_1itgoe">]</span><span class="__shiki_dzsirb">-&gt;</span><span class="__shiki_140thh">(b:City)</span></span>
